-- ============================================================
-- Tab class
-- ============================================================
LucidUI.Tab = {}
LucidUI.Tab.__index = LucidUI.Tab

function LucidUI.Window:CreateTab(config)
    config = config or {}

    local tab = setmetatable({}, LucidUI.Tab)
    tab.Name          = config.Name or "Tab"
    tab.Window        = self
    tab.Sections      = {}
    tab._orderCounter = 0
    tab.IconName      = config.Icon

    -- Resolve icon builder
    local builder = tab.IconName and LucidUI.IconBuilders[tab.IconName] or nil
    if tab.IconName and not builder then
        builder = LucidUI.IconBuilders.default
    end

    -- Tab button
    local btn = Create("TextButton", {
        Name = tab.Name,
        Text = "",
        BackgroundColor3 = self.Theme.Surface,
        BackgroundTransparency = 1,
        AutoButtonColor = false,
        Size = UDim2.fromOffset(0, 30),
        ZIndex = 2,
        Parent = self.TabStrip,
    })
    Corner(8, btn)

    -- Icon
    local iconHolder, iconParts = nil, {}
    local ICON_SIZE = 14
    local ICON_PAD = 10

    if builder then
        iconHolder, iconParts = builder(btn, ICON_SIZE, self.Theme.TabInactive)
        iconHolder.Position = UDim2.fromOffset(ICON_PAD, (30 - ICON_SIZE) / 2)
        iconHolder.ZIndex = 3
    end

    -- Label
    local labelX = builder and (ICON_PAD + ICON_SIZE + 6) or 12
    local labelW = -(labelX + 12)

    local labelLbl = Create("TextLabel", {
        Text = tab.Name,
        Font = Enum.Font.GothamMedium,
        TextSize = 13,
        TextColor3 = self.Theme.TabInactive,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Center,
        Position = UDim2.fromOffset(labelX, 0),
        Size = UDim2.new(1, labelW, 1, 0),
        ZIndex = 3,
        Parent = btn,
    })

    local ts = TextService:GetTextSize(tab.Name, 13, Enum.Font.GothamMedium, Vector2.new(1000, 30))
    btn.Size = UDim2.fromOffset(ts.X + (labelX + 12), 30)

    tab.Button    = btn
    tab.Label     = labelLbl
    tab.IconParts = iconParts

    btn.MouseEnter:Connect(function()
        if tab == self.ActiveTab then return end
        Tween(btn, 0.15, { BackgroundTransparency = 0.7 }):Play()
    end)
    btn.MouseLeave:Connect(function()
        if tab == self.ActiveTab then return end
        Tween(btn, 0.15, { BackgroundTransparency = 1 }):Play()
    end)

    -- Page
    local page = Create("ScrollingFrame", {
        Name = tab.Name .. "Page",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = self.Theme.TextMuted,
        ScrollBarImageTransparency = 0.5,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        Visible = false,
        ZIndex = 2,
        Parent = self.Content,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = page,
    })
    Create("UIPadding", {
        PaddingRight = UDim.new(0, 6),
        PaddingBottom = UDim.new(0, 12),
        Parent = page,
    })
    tab.Page = page

    -- Theme callback: recolor button label and icon parts
    self:_registerTheme(function(t)
        local active = (tab == self.ActiveTab)
        local c = active and t.TabActive or t.TabInactive
        labelLbl.TextColor3 = c
        for _, p in ipairs(iconParts) do
            p.BackgroundColor3 = c
        end
    end)

    btn.MouseButton1Click:Connect(function()
        self:SelectTab(tab)
    end)

    table.insert(self.Tabs, tab)
    if not self.ActiveTab then
        self:SelectTab(tab)
    end

    return tab
end

function LucidUI.Window:SelectTab(tab)
    for _, t in ipairs(self.Tabs) do
        local active = (t == tab)
        t.Page.Visible = active

        local c = active and self.Theme.TabActive or self.Theme.TabInactive

        Tween(t.Button, 0.18, {
            BackgroundTransparency = active and 0.20 or 1,
        }):Play()
        Tween(t.Label, 0.18, {
            TextColor3 = c,
        }):Play()

        for _, p in ipairs(t.IconParts or {}) do
            Tween(p, 0.18, { BackgroundColor3 = c }):Play()
        end

        if active then
            t.Page.Position = UDim2.fromOffset(8, 0)
            Tween(t.Page, 0.20, { Position = UDim2.fromOffset(0, 0) }):Play()
        end
    end

    self.ActiveTab = tab
end

-- ============================================================
-- Section class
-- ============================================================
LucidUI.Section = {}
LucidUI.Section.__index = LucidUI.Section

function LucidUI.Tab:CreateSection(nameOrConfig)
    local cfg = type(nameOrConfig) == "table"
        and nameOrConfig
        or { Name = nameOrConfig }

    local section = setmetatable({}, LucidUI.Section)

    section.Name        = cfg.Name or ""
    section.Tab         = self
    section.Collapsible = cfg.Collapsible ~= false
    section.Expanded    = cfg.StartExpanded ~= false

    section._order      = self._orderCounter * 1000
    section._elemOrder  = section._order

    self._orderCounter = self._orderCounter + 1

    -- Header
    if section.Name ~= "" then
        local headerBtn = Create("TextButton", {
            Text = "",
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 22),
            LayoutOrder = section._order,
            ZIndex = 2,
            Parent = self.Page,
        })

        local arrowTxt = Create("TextLabel", {
            Text = section.Expanded and "v" or ">",
            Font = Enum.Font.GothamBold,
            TextSize = 13,
            TextColor3 = self.Window.Theme.TextMuted,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.fromOffset(2, 0),
            Size = UDim2.fromOffset(16, 22),
            ZIndex = 2,
            Parent = headerBtn,
        })

        local header = Create("TextLabel", {
            Text = section.Name:upper(),
            Font = Enum.Font.GothamBold,
            TextSize = 11,
            TextColor3 = self.Window.Theme.TextMuted,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.fromOffset(18, 0),
            Size = UDim2.new(1, -18, 1, 0),
            ZIndex = 2,
            Parent = headerBtn,
        })

        section.HeaderBtn = headerBtn
        section.Header    = header
        section.Arrow     = arrowTxt

        headerBtn.MouseButton1Click:Connect(function()
            if not section.Collapsible then return end
            section:SetExpanded(not section.Expanded)
        end)

        headerBtn.MouseEnter:Connect(function()
            Tween(header,   0.15, { TextColor3 = self.Window.Theme.TextPrimary }):Play()
            Tween(arrowTxt, 0.15, { TextColor3 = self.Window.Theme.TextPrimary }):Play()
        end)
        headerBtn.MouseLeave:Connect(function()
            Tween(header,   0.15, { TextColor3 = self.Window.Theme.TextMuted }):Play()
            Tween(arrowTxt, 0.15, { TextColor3 = self.Window.Theme.TextMuted }):Play()
        end)

        self.Window:_registerTheme(function(t)
            header.TextColor3   = t.TextMuted
            arrowTxt.TextColor3 = t.TextMuted
        end)
    end

    -- Wrapper owns the animated height
    local wrapper = Create("Frame", {
        Name = "Wrapper",
        Size = UDim2.new(1, 0, 0, 0),
        BackgroundTransparency = 1,
        ClipsDescendants = true,
        LayoutOrder = section._order + 1,
        ZIndex = 2,
        Parent = self.Page,
    })

    -- Container fits its children
    local container = Create("Frame", {
        Name = "Container",
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        ZIndex = 2,
        Parent = wrapper,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = container,
    })

    section.Wrapper   = wrapper
    section.Container = container

    -- After layout settles, set the correct initial height
    task.spawn(function()
        task.wait()
        task.wait()
        if not wrapper.Parent then return end

        if section.Expanded then
            -- Wrapper auto-sizes while expanded and stable
            wrapper.AutomaticSize = Enum.AutomaticSize.Y
        else
            wrapper.AutomaticSize = Enum.AutomaticSize.None
            wrapper.Size = UDim2.new(1, 0, 0, 0)
        end
    end)

    table.insert(self.Sections, section)
    return section
end

-- ============================================================
-- Deterministic height — read the container directly
-- ============================================================
function LucidUI.Section:_measureHeight()
    -- Container has AutomaticSize.Y, so Size.Y.Offset is the true content height
    -- (including inter-child list padding). This works even for elements
    -- that use AutomaticSize.Y themselves (TextDisplay, expanded dropdowns).
    local h = self.Container.Size.Y.Offset
    if h <= 0 then
        -- Fallback: sum children offsets for the first frame
        local total, count = 0, 0
        for _, child in ipairs(self.Container:GetChildren()) do
            if child:IsA("GuiObject") and child.Visible then
                total = total + child.Size.Y.Offset
                count = count + 1
            end
        end
        if count > 1 then total = total + (count - 1) * 8 end
        return total
    end
    return h
end

function LucidUI.Section:_nextOrder()
    self._elemOrder = self._elemOrder + 1
    return self._elemOrder
end

function LucidUI.Section:_track(frame)
    frame.Parent = self.Container
    return frame
end

-- ============================================================
-- Expand / collapse — smooth tween + auto-size at rest
-- ============================================================
function LucidUI.Section:SetExpanded(state, instant)
    if state == self.Expanded and not instant then return end
    self.Expanded = state
    if self.Arrow then self.Arrow.Text = state and "v" or ">" end

    local wrapper   = self.Wrapper
    local container = self.Container

    -- Snap, no animation
    if instant or not self.Collapsible then
        if state then
            wrapper.AutomaticSize = Enum.AutomaticSize.Y
        else
            wrapper.AutomaticSize = Enum.AutomaticSize.None
            wrapper.Size = UDim2.new(1, 0, 0, 0)
        end
        return
    end

    -- Capture the current visual height FIRST, before touching anything
    local currentHeight
    if wrapper.AutomaticSize == Enum.AutomaticSize.Y then
        currentHeight = container.Size.Y.Offset
    else
        currentHeight = wrapper.Size.Y.Offset
    end
    if currentHeight <= 0 then
        -- Fallback in case layout hasn't settled yet
        currentHeight = container.Size.Y.Offset
        if currentHeight <= 0 then currentHeight = 1 end
    end

    if state then
        -- EXPAND: start from 0, tween to measured height, then hand off to AutoSize
        wrapper.AutomaticSize = Enum.AutomaticSize.None
        wrapper.Size = UDim2.new(1, 0, 0, 0)

        local target = container.Size.Y.Offset
        if target <= 0 then target = 1 end

        local tween = TweenService:Create(wrapper, Ease.Out(0.30), {
            Size = UDim2.new(1, 0, 0, target),
        })
        tween:Play()
        tween.Completed:Connect(function()
            if self.Expanded then
                wrapper.AutomaticSize = Enum.AutomaticSize.Y
            end
        end)
    else
        -- COLLAPSE: lock to current height, tween down
        wrapper.AutomaticSize = Enum.AutomaticSize.None
        wrapper.Size = UDim2.new(1, 0, 0, currentHeight)

        TweenService:Create(wrapper, Ease.In(0.28), {
            Size = UDim2.new(1, 0, 0, 0),
        }):Play()
    end
end

-- ============================================================
-- Module: 09_elements.lua
-- ============================================================
--[[
    Elements — every interactive widget users will place inside sections.

    All elements:
      • Follow the same pattern: create Frame → attach to section container
        via section:_track(frame) → register a theme callback
      • Accept an optional Flag string. When set, their value is written
        to win._configData[flag] and restored via win:LoadConfig()
      • Return a wrapper { Instance, Flag, Set, Get } for external control
]]

-- ============================================================
-- Button
-- ============================================================
function LucidUI.Section:CreateButton(config)
    config = config or {}

    local win   = self.Tab.Window
    local theme = win.Theme

    local btn = Create("TextButton", {
        Text = "",
        BackgroundColor3 = theme.Surface,
        BackgroundTransparency = theme.SurfaceTrans,
        AutoButtonColor = false,
        Size = UDim2.new(1, 0, 0, 36),
        LayoutOrder = self:_nextOrder(),
        ZIndex = 2,
    })
    Corner(10, btn)

    local stroke = Stroke(theme.Border, 1, theme.BorderTrans + 0.05, btn)

    local label = Create("TextLabel", {
        Text = config.Name or "Button",
        Font = Enum.Font.GothamMedium,
        TextSize = 14,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 2,
        Parent = btn,
    })

    btn.MouseEnter:Connect(function()
        Tween(btn, 0.15, {
            BackgroundColor3 = theme.SurfaceHover,
            BackgroundTransparency = theme.SurfaceHoverTrans,
        }):Play()
    end)
    btn.MouseLeave:Connect(function()
        Tween(btn, 0.15, {
            BackgroundColor3 = theme.Surface,
            BackgroundTransparency = theme.SurfaceTrans,
            Size = UDim2.new(1, 0, 0, 36),
        }):Play()
    end)
    btn.MouseButton1Down:Connect(function()
        Tween(btn, 0.08, { Size = UDim2.new(0.97, 0, 0, 34) }):Play()
    end)
    btn.MouseButton1Up:Connect(function()
        Tween(btn, 0.15, { Size = UDim2.new(1, 0, 0, 36) }):Play()
    end)
    btn.MouseButton1Click:Connect(function()
        if config.Callback then pcall(config.Callback) end
    end)

    win:_registerTheme(function(t)
        btn.BackgroundColor3 = t.Surface
        label.TextColor3     = t.TextPrimary
        stroke.Color         = t.Border
    end)

    self:_track(btn)

    return {
        Instance = btn,
        SetText = function(_, text) label.Text = tostring(text) end,
    }
end

-- ============================================================
-- Toggle
-- ============================================================
function LucidUI.Section:CreateToggle(config)
    config = config or {}

    local win   = self.Tab.Window
    local theme = win.Theme
    local state = config.CurrentValue or false
    local flag  = config.Flag

    local row = Create("Frame", {
        BackgroundColor3 = theme.Surface,
        BackgroundTransparency = theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 40),
        LayoutOrder = self:_nextOrder(),
        ZIndex = 2,
    })
    Corner(10, row)

    local rowStroke = Stroke(theme.Border, 1, theme.BorderTrans + 0.05, row)

    local label = Create("TextLabel", {
        Text = config.Name or "Toggle",
        Font = Enum.Font.GothamMedium,
        TextSize = 14,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0),
        Size = UDim2.new(1, -80, 1, 0),
        ZIndex = 2,
        Parent = row,
    })

    local track = Create("Frame", {
        Size = UDim2.fromOffset(44, 24),
        Position = UDim2.new(1, -58, 0.5, -12),
        BackgroundColor3 = state and theme.Accent or theme.ToggleOff,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = row,
    })
    Corner(12, track)

    local knob = Create("Frame", {
        Size = UDim2.fromOffset(20, 20),
        Position = state
            and UDim2.new(1, -22, 0.5, -10)
            or  UDim2.fromOffset(2, 2),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = track,
    })
    Corner(10, knob)

    local clickArea = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        ZIndex = 2,
        Parent = row,
    })

    local function update(value, silent)
        state = value
        Tween(track, 0.22, {
            BackgroundColor3 = state and theme.Accent or theme.ToggleOff,
        }, Enum.EasingStyle.Quart):Play()
        Tween(knob, 0.22, {
            Position = state
                and UDim2.new(1, -22, 0.5, -10)
                or  UDim2.fromOffset(2, 2),
        }, Enum.EasingStyle.Quart):Play()

        if flag then win._configData[flag] = state end
        if not silent and config.Callback then pcall(config.Callback, state) end
    end

    clickArea.MouseButton1Click:Connect(function()
        update(not state)
    end)
    clickArea.MouseEnter:Connect(function()
        Tween(row, 0.15, {
            BackgroundTransparency = math.max(theme.SurfaceTrans - 0.1, 0),
        }):Play()
    end)
    clickArea.MouseLeave:Connect(function()
        Tween(row, 0.15, { BackgroundTransparency = theme.SurfaceTrans }):Play()
    end)

    win:_registerTheme(function(t)
        row.BackgroundColor3 = t.Surface
        label.TextColor3     = t.TextPrimary
        rowStroke.Color      = t.Border
        track.BackgroundColor3 = state and t.Accent or t.ToggleOff
    end)

    local obj = {
        Instance = row,
        Flag = flag,
        Set = function(_, value) update(value, true) end,
        Get = function() return state end,
    }

    if flag then
        win._elementsByFlag[flag] = obj
        win._configData[flag] = state
    end

    self:_track(row)
    return obj
end

-- ============================================================
-- Slider
-- ============================================================
function LucidUI.Section:CreateSlider(config)
    config = config or {}

    local win   = self.Tab.Window
    local theme = win.Theme

    local min   = (config.Range and config.Range[1]) or 0
    local max   = (config.Range and config.Range[2]) or 100
    local value = config.CurrentValue or min
    local inc   = config.Increment or 1
    local flag  = config.Flag

    local row = Create("Frame", {
        BackgroundColor3 = theme.Surface,
        BackgroundTransparency = theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, 54),
        LayoutOrder = self:_nextOrder(),
        ZIndex = 2,
    })
    Corner(10, row)

    local rowStroke = Stroke(theme.Border, 1, theme.BorderTrans + 0.05, row)

    local nameLabel = Create("TextLabel", {
        Text = config.Name or "Slider",
        Font = Enum.Font.GothamMedium,
        TextSize = 14,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 6),
        Size = UDim2.new(1, -28, 0, 18),
        ZIndex = 2,
        Parent = row,
    })

    local valueLabel = Create("TextLabel", {
        Text = tostring(value),
        Font = Enum.Font.GothamBold,
        TextSize = 13,
        TextColor3 = theme.Accent,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Right,
        Position = UDim2.fromOffset(14, 6),
        Size = UDim2.new(1, -28, 0, 18),
        ZIndex = 2,
        Parent = row,
    })

    local track = Create("Frame", {
        Size = UDim2.new(1, -28, 0, 4),
        Position = UDim2.new(0, 14, 1, -16),
        BackgroundColor3 = theme.SliderTrack,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = row,
    })
    Corner(2, track)

    local fill = Create("Frame", {
        Size = UDim2.new((value - min) / (max - min), 0, 1, 0),
        BackgroundColor3 = theme.Accent,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = track,
    })
    Corner(2, fill)

    local handle = Create("Frame", {
        Size = UDim2.fromOffset(18, 18),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new((value - min) / (max - min), 0, 0.5, 0),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = track,
    })
    Corner(9, handle)
    Stroke(theme.Border, 1, 0.7, handle)

    local drag = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0),
        ZIndex = 3,
        Parent = track,
    })

    local dragging = false

    local function setFromInput(input)
        local rel = math.clamp(
            (input.Position.X - track.AbsolutePosition.X) / track.AbsoluteSize.X,
            0, 1
        )
        local raw = min + (max - min) * rel
        value = math.floor((raw / inc) + 0.5) * inc
        value = math.clamp(value, min, max)

        fill.Size        = UDim2.new((value - min) / (max - min), 0, 1, 0)
        handle.Position  = UDim2.new((value - min) / (max - min), 0, 0.5, 0)
        valueLabel.Text  = tostring(value)
    end

    drag.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            Tween(handle, 0.10, { Size = UDim2.fromOffset(22, 22) }):Play()
            setFromInput(input)
            if flag then win._configData[flag] = value end
            if config.Callback then pcall(config.Callback, value) end
        end
    end)

    table.insert(win._conns, UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            setFromInput(input)
            if flag then win._configData[flag] = value end
            if config.Callback then pcall(config.Callback, value) end
        end
    end))

    table.insert(win._conns, UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
            Tween(handle, 0.15, { Size = UDim2.fromOffset(18, 18) }):Play()
        end
    end))

    win:_registerTheme(function(t)
        row.BackgroundColor3    = t.Surface
        nameLabel.TextColor3    = t.TextPrimary
        valueLabel.TextColor3   = t.Accent
        track.BackgroundColor3  = t.SliderTrack
        fill.BackgroundColor3   = t.Accent
        rowStroke.Color         = t.Border
    end)

    local obj = {
        Instance = row,
        Flag = flag,
        Set = function(_, v)
            v = math.clamp(v, min, max)
            value = v
            fill.Size       = UDim2.new((value - min) / (max - min), 0, 1, 0)
            handle.Position = UDim2.new((value - min) / (max - min), 0, 0.5, 0)
            valueLabel.Text = tostring(value)
            if flag then win._configData[flag] = value end
        end,
        Get = function() return value end,
    }

    if flag then
        win._elementsByFlag[flag] = obj
        win._configData[flag] = value
    end

    self:_track(row)
    return obj
end

-- ============================================================
-- Dropdown
-- ============================================================
function LucidUI.Section:CreateDropdown(config)
    config = config or {}

    local win   = self.Tab.Window
    local theme = win.Theme

    local options   = config.Options or {}
    local value     = config.CurrentOption or options[1] or ""
    local expanded  = false
    local flag      = config.Flag

    local ROW_H, OPT_H, OPT_P = 40, 32, 4

    local row = Create("Frame", {
        BackgroundColor3 = theme.Surface,
        BackgroundTransparency = theme.SurfaceTrans,
        Size = UDim2.new(1, 0, 0, ROW_H),
        ClipsDescendants = true,
        LayoutOrder = self:_nextOrder(),
        ZIndex = 2,
    })
    Corner(10, row)

    local rowStroke = Stroke(theme.Border, 1, theme.BorderTrans + 0.05, row)

    local headerBtn = Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, ROW_H),
        ZIndex = 2,
        Parent = row,
    })

    local nameLabel = Create("TextLabel", {
        Text = config.Name or "Dropdown",
        Font = Enum.Font.GothamMedium,
        TextSize = 14,
        TextColor3 = theme.TextPrimary,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(14, 0),
        Size = UDim2.new(1, -100, 1, 0),
        ZIndex = 2,
        Parent = headerBtn,
    })

    local valueLabel = Create("TextLabel", {
        Text = tostring(value),
        Font = Enum.Font.GothamMedium,
        TextSize = 13,
        TextColor3 = theme.Accent,
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Right,
        Size = UDim2.new(1, -40, 1, 0),
        ZIndex = 2,
        Parent = headerBtn,
    })

    local arrowLbl = Create("TextLabel", {
        Text = "v",
        Font = Enum.Font.GothamBold,
        TextSize = 14,
        TextColor3 = theme.TextMuted,
        BackgroundTransparency = 1,
        Position = UDim2.new(1, -24, 0, 0),
        Size = UDim2.fromOffset(20, ROW_H),
        ZIndex = 2,
        Parent = headerBtn,
    })

    local list = Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        Position = UDim2.fromOffset(10, ROW_H),
        BackgroundTransparency = 1,
        ClipsDescendants = true,
        ZIndex = 2,
        Parent = row,
    })
    Create("UIListLayout", {
        Padding = UDim.new(0, OPT_P),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = list,
    })

    local optionBtns = {}
    for i, opt in ipairs(options) do
        local optBtn = Create("TextButton", {
            Text = tostring(opt),
            Font = Enum.Font.GothamMedium,
            TextSize = 13,
            TextColor3 = theme.TextPrimary,
            BackgroundColor3 = theme.Background,
            BackgroundTransparency = 0.5,
            AutoButtonColor = false,
            Size = UDim2.new(1, 0, 0, OPT_H),
            LayoutOrder = i,
            ZIndex = 2,
            Parent = list,
        })
        Corner(8, optBtn)

        optBtn.MouseEnter:Connect(function()
            Tween(optBtn, 0.12, {
                BackgroundColor3 = theme.Accent,
                BackgroundTransparency = 0.3,
            }):Play()
        end)
        optBtn.MouseLeave:Connect(function()
            Tween(optBtn, 0.12, {
                BackgroundColor3 = theme.Background,
                BackgroundTransparency = 0.5,
            }):Play()
        end)

        optBtn.MouseButton1Click:Connect(function()
            value = opt
            valueLabel.Text = tostring(opt)
            expanded = false
            Tween(list, 0.22, { Size = UDim2.new(1, -20, 0, 0) }):Play()
            Tween(row,  0.22, { Size = UDim2.new(1, 0, 0, ROW_H) }):Play()
            Tween(arrowLbl, 0.20, { Rotation = 0 }):Play()

            if flag then win._configData[flag] = value end
            if config.Callback then pcall(config.Callback, opt) end
        end)

        table.insert(optionBtns, optBtn)
    end

    headerBtn.MouseButton1Click:Connect(function()
        expanded = not expanded
        local openH = #options * (OPT_H + OPT_P) + 8
        Tween(list, 0.22, {
            Size = UDim2.new(1, -20, 0, expanded and openH or 0),
        }, Enum.EasingStyle.Quart):Play()
        Tween(row, 0.22, {
            Size = UDim2.new(1, 0, 0, expanded and (ROW_H + openH + 8) or ROW_H),
        }, Enum.EasingStyle.Quart):Play()
        Tween(arrowLbl, 0.20, { Rotation = expanded and 180 or 0 }):Play()
    end)

    win:_registerTheme(function(t)
        row.BackgroundColor3    = t.Surface
        nameLabel.TextColor3    = t.TextPrimary
        valueLabel.TextColor3   = t.Accent
        arrowLbl.TextColor3     = t.TextMuted
        rowStroke.Color         = t.Border
        for _, ob in ipairs(optionBtns) do
            ob.BackgroundColor3 = t.Background
            ob.TextColor3       = t.TextPrimary
        end
    end)

    local obj = {
        Instance = row,
        Flag = flag,
        Set = function(_, v)
            value = v
            valueLabel.Text = tostring(v)
            if flag then win._configData[flag] = value end
        end,
        Get = function() return value end,
    }

    if flag then
        win._elementsByFlag[flag] = obj
        win._configData[flag] = value
    end

    self:_track(row)
    return obj
end

